DISCLOSED_WIDENINGS: List[Dict[str, str]] = [
    {
        "path": "docs/ARCHITECTURE.md",
        "why": "2026-08-23: the `*.md` glob froze every paragraph of prose in the tree, so "
               "the ops engine could not retire a component and the kit's own corpus (all "
               "markdown) was unmaintainable. Narrowed to named identity documents. Ordinary "
               "prose is deletable behind MAX_DELETIONS=3, a mandatory reason and a backup; "
               "a project restores the old behaviour with CLAUDEKIT_EXTRA_PROTECTED='*.md'.",
    },
]
_DISCLOSED_PREFIXES = (
    "docs/", ".ai/", ".github/", ".claude/skills/", ".claude/agents/", "templates/",
)

def _is_disclosed(path: str) -> bool:
    """A path is a disclosed widening if it is named, or matches the prose-tree prefixes
    the single disclosed entry covers. Kept explicit rather than blanket-allowing `*.md`:
    an identity document that lost protection must still fail."""
    for entry in DISCLOSED_WIDENINGS:
        if entry["path"] == path:
            return True
    return path.endswith(".md") and path.startswith(_DISCLOSED_PREFIXES)
